/** Derived measures follow the workbook's own formula pattern (transparent, labelled derived in UI):
 *   practicalDaily  = round(0.65 x theoreticalDaily)   (verified against all 9 sampled sheet1 rows)
 *   dailyAvailable  = practicalDaily - lostTSR - lostMA + infraRecovery + unusedFromTOCs
 *   weeklyPractical = practicalDaily x 7
 *   weeklyAllocated = sum(tocAllocated)
 *   weeklySpare     = weeklyPractical - weeklyAllocated
 * The workbook caches its own values in the snapshot; the UI recomputes from Capacity_DB raw columns. */
export const derivedFormulas = {
  practicalDaily: "round(0.65 x theoreticalDaily)",
  dailyAvailable: "practicalDaily - lostTSR - lostMA + infraRecovery + unusedFromTOCs",
  weeklyPractical: "practicalDaily x 7",
  weeklyAllocated: "sum(tocAllocated TOC 1..15)",
  weeklySpare: "weeklyPractical - weeklyAllocated",
};
